     1	package hotel;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	import java.util.Map;
     6	import javax.sql.DataSource;
     7	import org.flywaydb.core.Flyway;
     8	
     9	/**
    10	 * The connections to the inn's PostgreSQL: the address comes in DB_URL (jdbc:postgresql://host:port/database), the
    11	 * user in DB_USER and the password in DB_PASSWORD. Opening it brings the schema up to date with the migrations in
    12	 * src/main/resources/db/migration.
    13	 */
    14	public final class Database implements AutoCloseable {
    15	
    16	    private final HikariDataSource dataSource;
    17	
    18	    public Database(Map<String, String> environment) {
    19	        String url = environment.get("DB_URL");
    20	        if (url == null || url.isBlank()) {
    21	            throw new IllegalStateException("DB_URL is not set: it must hold the PostgreSQL address");
    22	        }
    23	        HikariConfig config = new HikariConfig();
    24	        config.setJdbcUrl(url);
    25	        config.setUsername(environment.get("DB_USER"));
    26	        config.setPassword(environment.get("DB_PASSWORD"));
    27	        this.dataSource = new HikariDataSource(config);
    28	        Flyway.configure().dataSource(dataSource).load().migrate();
    29	    }
    30	
    31	    public DataSource dataSource() {
    32	        return dataSource;
    33	    }
    34	
    35	    @Override
    36	    public void close() {
    37	        dataSource.close();
    38	    }
    39	}
