     1	package hotel;
     2	
     3	import hotel.messages.EmailSender;
     4	import hotel.messages.SentMessages;
     5	import hotel.reports.OccupancyReport;
     6	import hotel.reports.RevenueReport;
     7	import hotel.reservations.PriceCalculator;
     8	import hotel.reservations.ReservationService;
     9	import hotel.reservations.ReservationStore;
    10	import hotel.rooms.Rooms;
    11	import hotel.web.HttpApi;
    12	import io.javalin.Javalin;
    13	import javax.sql.DataSource;
    14	
    15	/** Puts the inn's pieces together and runs the HTTP server. */
    16	public final class Hotel {
    17	
    18	    private final Javalin server;
    19	
    20	    public Hotel(DataSource dataSource) {
    21	        Rooms rooms = new Rooms(dataSource);
    22	        ReservationStore store = new ReservationStore(dataSource);
    23	        SentMessages sentMessages = new SentMessages(dataSource);
    24	        ReservationService reservations =
    25	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
    26	        HttpApi api = new HttpApi(
    27	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
    28	        this.server = api.server();
    29	    }
    30	
    31	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    32	    public int start(int port) {
    33	        server.start(port);
    34	        return server.port();
    35	    }
    36	
    37	    public void stop() {
    38	        server.stop();
    39	    }
    40	
    41	    public static void main(String[] args) {
    42	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    43	        Database database = new Database(System.getenv());
    44	        new Hotel(database.dataSource()).start(port);
    45	    }
    46	}
