   128	        return "Olá, " + reservation.guest().name() + "!\n\n"
   129	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   130	                + receipt.text() + "\n"
   131	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   132	                + "Até breve!\n";
   133	    }
