   129	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"),
   130	                row.getString("company_cnpj"), row.getString("company_name"), row.getString("guest_passport"),
   131	                row.getString("guest_country"));
